        static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);checks++;Console.WriteLine("PASS "+name);}
        static IEnumerable<T> All<T>(DependencyObject p)where T:DependencyObject{if(p is T)yield return(T)p;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)foreach(var t in All<T>(VisualTreeHelper.GetChild(p,i)))yield return t;}
        static Button Button(DependencyObject p,string id){return All<Button>(p).Single(b=>b.Name==id);}static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));}
        static IEnumerable<MenuItem> MenuItems(ItemsControl menu){foreach(MenuItem item in menu.Items.OfType<MenuItem>()){yield return item;foreach(var child in MenuItems(item))yield return child;}}
        static MenuItem Menu(ImageWorkspacePage page,string name){return MenuItems(Button(page,"ImageGalleryFilter").ContextMenu).Single(m=>m.Name==name);}
        static async Task ChooseMenu(ImageWorkspacePage page,string name,string value=null){Click(Button(page,"ImageGalleryFilter"));await Task.Delay(20);var item=MenuItems(Button(page,"ImageGalleryFilter").ContextMenu).Single(m=>m.Name==name&&(value==null||m.Header as string==value));var chain=new List<MenuItem>();for(var parent=ItemsControl.ItemsControlFromItemContainer(item) as MenuItem;parent!=null;parent=ItemsControl.ItemsControlFromItemContainer(parent) as MenuItem)chain.Insert(0,parent);foreach(var parent in chain){parent.IsSubmenuOpen=true;await Task.Delay(20);}typeof(MenuItem).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(item,null);Button(page,"ImageGalleryFilter").ContextMenu.IsOpen=false;await Task.Delay(30);}
        static async Task Layout(ImageWorkspacePage page,int index){var dropdown=All<ComboBox>(page).Single(c=>c.Name=="GalleryLayout");dropdown.IsDropDownOpen=true;await Task.Delay(20);dropdown.SelectedIndex=index;dropdown.IsDropDownOpen=false;await Task.Delay(50);}
        static void Capture(Window window,string name){window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth),(int)Math.Ceiling(window.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(root,name)))encoder.Save(file);}
        static void GenerationFailure(Window host,ImageWorkspacePage page,string reason)
        {
            var scroll=All<ScrollViewer>(page).Single(v=>v.Name=="ImageGenerationScroll");
            var lines=new List<string>{reason,"WorkArea="+SystemParameters.WorkArea,"Host="+host.ActualWidth+"x"+host.ActualHeight,"Page="+page.ActualWidth+"x"+page.ActualHeight,"Scroll viewport="+scroll.ViewportWidth+"x"+scroll.ViewportHeight+" extent="+scroll.ExtentWidth+"x"+scroll.ExtentHeight+" offset="+scroll.HorizontalOffset+","+scroll.VerticalOffset};
            foreach(var element in All<FrameworkElement>(page).Where(e=>new[]{"ImageGenerationLayout","ImageGenerationParameters","ImageGenerationPreview","ImagePromptComposer","WorkspaceGeneratedImage","StartImageGeneration","ImageReferenceUpload"}.Contains(e.Name)))lines.Add(element.Name+" bounds="+new Rect(element.TranslatePoint(new Point(),page),element.RenderSize)+" desired="+element.DesiredSize);
            foreach(var image in All<Image>(page).Where(i=>i.Name=="WorkspaceGeneratedImage")){var bitmap=image.Source as BitmapSource;lines.Add(image.Name+" loaded="+image.IsLoaded+" visible="+image.IsVisible+" measureValid="+image.IsMeasureValid+" arrangeValid="+image.IsArrangeValid+" source="+(bitmap==null?"none":bitmap.PixelWidth+"x"+bitmap.PixelHeight));}
            string detail=String.Join(Environment.NewLine,lines);Console.Error.WriteLine(detail);File.WriteAllText(Path.Combine(root,"generation-layout-failure.txt"),detail);Capture(host,"generation-layout-failure.png");
        }
        static Rect Bounds(FrameworkElement element,UIElement relative){return new Rect(element.TranslatePoint(new Point(),relative),element.RenderSize);}
        static bool Fits(Rect viewport,Rect bounds){viewport.Inflate(1,1);return viewport.Contains(bounds);}
        static async Task SettleLayout(Window host){host.UpdateLayout();await host.Dispatcher.InvokeAsync(new Action(host.UpdateLayout),System.Windows.Threading.DispatcherPriority.Normal).Task;}
        static async Task<Image> WaitForWorkspacePreview(Window host,ImageWorkspacePage page)
        {
            var elapsed=System.Diagnostics.Stopwatch.StartNew();
            while(elapsed.ElapsedMilliseconds<5000)
            {
                var preview=All<WorkspaceImagePreview>(page).SingleOrDefault();
                var image=preview==null?null:All<Image>(preview).SingleOrDefault();
                var bitmap=image==null?null:image.Source as BitmapSource;
                // Replacement runs from Loaded/dispatcher callbacks; existence alone precedes layout.
                if(image!=null&&image.IsLoaded&&image.IsVisible&&image.IsMeasureValid&&image.IsArrangeValid&&bitmap!=null&&bitmap.PixelWidth>0&&bitmap.PixelHeight>0&&image.RenderSize.Width>0&&image.RenderSize.Height>0)return image;
                await Task.Delay(20);
            }
            const string reason="workspace preview did not become loaded, decoded and arranged within five seconds";
            GenerationFailure(host,page,reason);throw new Exception(reason);
        }
        static void GenerationCheck(bool value,Window host,ImageWorkspacePage page,string name){if(!value)GenerationFailure(host,page,name);Check(value,name);}
        static async Task CompletedGenerationLayoutChecks(ChatWindow chat,ImageWorkspacePage page)
        {
            double originalHeight=chat.Height;chat.Width=560;
            // Ui.Window bounds the initial host to the monitor work area. Short hosts deliberately scroll.
            foreach(double requestedHeight in new[]{originalHeight,692.0,560.0}.Distinct())
            {
                chat.Height=Math.Min(requestedHeight,SystemParameters.WorkArea.Height-36);await SettleLayout(chat);
                var scroll=All<ScrollViewer>(page).Single(v=>v.Name=="ImageGenerationScroll");scroll.ScrollToTop();await SettleLayout(chat);
                var composer=All<Border>(page).Single(b=>b.Name=="ImagePromptComposer");var preview=All<Image>(All<WorkspaceImagePreview>(page).Single()).Single();
                var viewport=new Rect(scroll.TranslatePoint(new Point(),page),new Size(scroll.ViewportWidth,scroll.ViewportHeight));var composerBounds=Bounds(composer,page);var previewBounds=Bounds(preview,page);
                string fixture="narrow completed host "+chat.ActualWidth+"x"+chat.ActualHeight;
                Console.WriteLine(fixture+" viewport="+viewport.Size+" extent="+scroll.ExtentWidth+","+scroll.ExtentHeight+" scrollable="+scroll.ScrollableHeight);
                GenerationCheck(composerBounds.Left>=viewport.Left-1&&composerBounds.Right<=viewport.Right+1&&previewBounds.Left>=viewport.Left-1&&previewBounds.Right<=viewport.Right+1&&preview.ActualWidth>200,chat,page,fixture+" keeps large preview and composer within horizontal viewport");
                if(chat.ActualHeight>=800)GenerationCheck(scroll.ScrollableHeight<=1&&Fits(viewport,composerBounds)&&Fits(viewport,previewBounds),chat,page,fixture+" fits complete preview and composer without scrolling");
                if(requestedHeight==560)GenerationCheck(scroll.ScrollableHeight>1,chat,page,fixture+" exposes vertical scrolling for full size result and composer");
                preview.BringIntoView();await SettleLayout(chat);GenerationCheck(Fits(viewport,Bounds(preview,page)),chat,page,fixture+" scroll reaches complete preview");
                Capture(chat,"generation-result-narrow-preview-"+(int)chat.ActualHeight+".png");
                composer.BringIntoView();await SettleLayout(chat);GenerationCheck(Fits(viewport,Bounds(composer,page))&&Fits(viewport,Bounds(Button(page,"StartImageGeneration"),page))&&Fits(viewport,Bounds(Button(page,"ImageReferenceUpload"),page)),chat,page,fixture+" scroll reaches complete composer and generation/reference actions");
                Capture(chat,"generation-result-narrow-"+(int)chat.ActualHeight+".png");
                if(requestedHeight==originalHeight)Capture(chat,"generation-result-narrow.png");
            }
            chat.Height=originalHeight;await SettleLayout(chat);
        }
        static async Task CaptureGallery(ChatWindow chat,ImageWorkspacePage page,string name){await Task.Delay(30);for(int wait=0;wait<1000&&All<ImageGalleryTile>(page).Any(t=>All<Image>(t).Single().Source==null);wait++)await Task.Delay(10);Check(All<ImageGalleryTile>(page).All(t=>All<Image>(t).Single().Source!=null),"gallery capture waits for decoded images "+name);Capture(chat,name);}
        static string ArrowMetrics(FrameworkElement control,System.Windows.Shapes.Path standard)
        {
            var arrow=All<System.Windows.Shapes.Path>(control).Single(a=>a.Data!=null&&Math.Abs(a.Data.Bounds.Width-8)<.01&&Math.Abs(a.Data.Bounds.Height-4)<.01);var dpi=VisualTreeHelper.GetDpi(control);
            var standardControl=(FrameworkElement)standard.TemplatedParent;double standardRight=standardControl.ActualWidth-standard.TranslatePoint(new Point(standard.ActualWidth,0),standardControl).X;double standardCenter=standard.TranslatePoint(new Point(0,standard.ActualHeight/2),standardControl).Y;var styled=control as Control;
            double right=control.ActualWidth-arrow.TranslatePoint(new Point(arrow.ActualWidth,0),control).X,center=arrow.TranslatePoint(new Point(0,arrow.ActualHeight/2),control).Y;
            return control.Name+" dpi="+dpi.DpiScaleX+","+dpi.DpiScaleY+" bounds="+Bounds(control,Window.GetWindow(control))+" arrow="+Bounds(arrow,control)+" geometry="+arrow.Data.ToString(System.Globalization.CultureInfo.InvariantCulture)+" geometryMatch="+(arrow.Data.ToString(System.Globalization.CultureInfo.InvariantCulture)==standard.Data.ToString(System.Globalization.CultureInfo.InvariantCulture))+" stroke="+arrow.StrokeThickness+" margin="+arrow.Margin+" right="+right+" rightDevicePixels="+(right*dpi.DpiScaleX)+" standardRight="+standardRight+" rightDelta="+(right-standardRight)+" font="+styled.FontFamily+" fontSize="+styled.FontSize+" center="+center+" expectedCenter="+control.ActualHeight/2+" centerDelta="+(center-control.ActualHeight/2)+" standardCenter="+standardCenter+" centerDeltaNative="+(center-standardCenter)+" color="+((SolidColorBrush)arrow.Stroke).Color+" standardColor="+((SolidColorBrush)standard.Stroke).Color;
        }
