        static void SetVisualDpi(ChatWindow chat,DpiScale dpi)
        {
            VisualTreeHelper.SetRootDpi(chat,dpi);
            // SetRootDpi changes visual DPI without the native WM_DPICHANGED invalidation.
            foreach(var element in All<FrameworkElement>(chat).ToArray()){element.InvalidateMeasure();element.InvalidateArrange();}
            chat.UpdateLayout();
        }
