        static byte[] LayoutPicture(int width,int height,int hue)
        {
            var visual=new DrawingVisual();using(var draw=visual.RenderOpen()){draw.DrawRectangle(new LinearGradientBrush(Color.FromRgb((byte)(40+hue*15),100,160),Color.FromRgb(200,(byte)(80+hue*12),120),45),null,new Rect(0,0,width,height));draw.DrawEllipse(new SolidColorBrush(Color.FromArgb(100,255,255,255)),null,new Point(width*.55,height*.45),width*.3,Math.Min(width,height)*.28);}
            var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=new MemoryStream()){encoder.Save(output);return output.ToArray();}
        }
