        static async Task<System.Windows.Shapes.Path> WaitForGalleryHeart(DependencyObject page,string id,bool favorite)
        {
            var elapsed=System.Diagnostics.Stopwatch.StartNew();System.Windows.Shapes.Path heart=null;
            while(elapsed.ElapsedMilliseconds<5000)
            {
                var tile=All<ImageGalleryTile>(page).FirstOrDefault(item=>item.Asset.Id==id);
                var button=tile==null?null:All<Button>(tile).FirstOrDefault(item=>item.Name=="GalleryTileFavorite");
                heart=button==null?null:button.Content as System.Windows.Shapes.Path;
                var fill=heart==null?null:heart.Fill as SolidColorBrush;
                if(heart!=null&&heart.IsLoaded&&heart.IsMeasureValid&&heart.IsArrangeValid&&heart.RenderSize.Width>0&&heart.RenderSize.Height>0&&fill!=null&&(fill.Color.A>0)==favorite&&tile.Asset.IsFavorite==favorite)return heart;
                await Task.Delay(20);
            }
            throw new Exception("Gallery heart did not reach an arranged favorite state: favorite="+favorite+" size="+(heart==null?"missing":heart.RenderSize.ToString()));
        }
